{"command":"cd "$(pwd)"; cat > gcmbench.c <<'EOF'
#include <openssl/evp.h>
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <time.h>
int main(){
    unsigned char key[16]={0}, nonce[12]={0};
    size_t len = 61440000;
    unsigned char *pt = malloc(len);
    unsigned char *ct = malloc(len+16);
    unsigned char tag[16];
    memset(pt,0,len);
    // warm
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_aes_128_gcm(), NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, 12, NULL);
    EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
    int outl=0, fin=0;
    EVP_EncryptUpdate(ctx, ct, &outl, pt, len);
    EVP_EncryptFinal_ex(ctx, ct+outl, &fin);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag);
    EVP_CIPHER_CTX_free(ctx);
    for(int i=0;i<10;i++){
        struct timespec a,b;
        clock_gettime(CLOCK_MONOTONIC, &a);
        ctx = EVP_CIPHER_CTX_new();
        EVP_EncryptInit_ex(ctx, EVP_aes_128_gcm(), NULL, NULL, NULL);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, 12, NULL);
        EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
        outl=0; fin=0;
        EVP_EncryptUpdate(ctx, ct, &outl, pt, len);
        EVP_EncryptFinal_ex(ctx, ct+outl, &fin);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag);
        EVP_CIPHER_CTX_free(ctx);
        clock_gettime(CLOCK_MONOTONIC, &b);
        double dt = (b.tv_sec-a.tv_sec) + (b.tv_nsec-a.tv_nsec)/1e9;
        printf("%.4f ms\n", dt*1000);
    }
    return 0;
}
EOF
export TMPDIR="$(pwd)"; /Library/Developer/CommandLineTools/usr/bin/clang -O2 -isysroot /Library/Developer/CommandLineTools/SDKs/MacOSX.sdk -I/usr/local/include -L/usr/local/lib -lcrypto gcmbench.c -o gcmbench 2>&1; echo "exit $?"; ./gcmbench"}
